import { Link } from 'react-router-dom';
import Data from '../Data.js';
import { IoArrowForwardOutline, IoMailOutline } from 'react-icons/io5';

const Sidebar = ({ travelId }) => {
  const categories = ["Beaches", "Cities", "Culture", "History", "Nature"];

  // Get 3 recent posts excluding current
  const recentPosts = Data
    .filter(item => item.id !== travelId)
    .slice(0, 3);

  return (
    <aside className="sidebar">
      <div className="sidebar-section">
        <h3 className="sidebar-title">About Trip Tips</h3>
        <p className="sidebar-text">
          Our mission is to inspire and empower travelers to explore the world's most
          captivating destinations with curated insights.
        </p>
      </div>

      <div className="sidebar-section">
        <h3 className="sidebar-title">Categories</h3>
        <div className="sidebar-categories">
          {categories.map(cat => (
            <Link key={cat} to="/" className="sidebar-cat-pill">
              {cat}
            </Link>
          ))}
        </div>
      </div>

      <div className="sidebar-section">
        <h3 className="sidebar-title">Recent Adventures</h3>
        <div className="recent-posts-list">
          {recentPosts.map(post => (
            <Link key={post.id} to="/details" state={{ travelData: post }} className="recent-post-item">
              <div className="recent-post-thumb">
                <img src={post.img} alt={post.title} />
              </div>
              <div className="recent-post-info">
                <h4>{post.title}</h4>
                <span>{post.startDate.split(' ')[2]}</span>
              </div>
            </Link>
          ))}
        </div>
      </div>

      <div className="sidebar-section newsletter">
        <h3 className="sidebar-title">Stay Inspired</h3>
        <p>Get the latest travel tips directly in your inbox.</p>
        <div className="newsletter-form">
          <IoMailOutline />
          <input type="email" placeholder="Your email..." />
          <button><IoArrowForwardOutline /></button>
        </div>
      </div>
    </aside>
  );
};

export default Sidebar;
